var routeSets = [][]string{
	{"/"},
	{"/", "/users/:id"},
	{"/", "/*"},
	{"/", "/users/:id", "/*"},
	{"/users/create", "/users/:id/edit", "/users/:id/active"},
	{"/a", "/b/:c", "/d/*"},
	{"/:a", "/:a/b", "/*"},
	{"/a/:b/c", "/a/:b/d", "/a/e"},
	{"/users/:id", "/users/:id/edit"},
	{"/x/*", "/x/y"},
	{"/:a", "/:a/:b", "/:a/:b/:c"},
	{"/a/b/c", "/a/:b/c", "/a/*"},
	{"/*", "/:a", "/static"},
	{"/", "/:a", "/:a/*"},
	{"/:a/b", "/*", "/c"},
}

var paths = []string{"", "/", "//", "noslash", "a", "/a", "/b", "/c", "/d", "/x", "/x/y", "/x/y/z", "/users", "/users/1", "/users/1/edit", "/a/b/c", "/a/b", "/static", "/static/x", "/:", "/:a", "/%2F", "/a/b/c/d"}

func TestZZFuzzFind(t *testing.T) {
	for ri, rs := range routeSets {
		e := New()
		for _, r := range rs {
			e.router.Add(http.MethodGet, r, func(c Context) error { return nil })
		}
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Errorf("PANIC routes=%v path=%q: %v", rs, p, rec)
					}
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(http.MethodGet, p, c)
				if c.Handler() == nil {
					t.Errorf("nil handler routes=%v path=%q", rs, p)
				}
			}()
		}
		_ = ri
	}
}

func TestZZFuzzAddFind(t *testing.T) {
	// add routes in all orders, then find
	for ri, rs := range routeSets {
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Errorf("PANIC add routes=%v path=%q: %v", rs, p, rec)
					}
