func TestZZFuzzRandom(t *testing.T) {
	seg := []string{"a", "b", "c", ":p", "*", "x"}
	rand.Seed(1)
	for iter := 0; iter < 3000; iter++ {
		e := New()
		n := rand.Intn(6)
		var routes []string
		for i := 0; i < n; i++ {
			depth := rand.Intn(4)
			p := ""
			for d := 0; d < depth; d++ {
				p += "/" + seg[rand.Intn(len(seg))]
			}
			if p == "" {
				p = "/"
			}
			routes = append(routes, p)
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("PANIC Add route=%q routes=%v: %v", p, routes, r)
					}
				}()
				e.router.Add(http.MethodGet, p, func(c Context) error { return nil })
			}()
		}
		for k := 0; k < 12; k++ {
			depth := rand.Intn(5)
			p := ""
			for d := 0; d < depth; d++ {
				p += "/" + seg[rand.Intn(len(seg))]
			}
			if rand.Intn(5) == 0 && len(p) > 0 {
				p = p[1:] // no leading slash
			}
			if rand.Intn(7) == 0 {
				p = ""
			}
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("PANIC Find routes=%v path=%q: %v", routes, p, r)
					}
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(http.MethodGet, p, c)
				if c.Handler() == nil {
					t.Fatalf("nil handler routes=%v path=%q", routes, p)
				}
			}()
		}
	}
}
