func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header, HeaderXForwardedProto); scheme != "" {
		return scheme
	}
	if scheme := schemeFromHeader(c.request.Header, HeaderXForwardedProtocol); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := schemeFromHeader(c.request.Header, HeaderXUrlScheme); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the scheme from the given header when its value is a
// valid HTTP scheme (`http` or `https`). Invalid values are ignored so that the
// next header can be consulted and the scheme falls back to `http`.
