## Bug & fix

**Bug** (`/echo/context.go`, `context.Scheme()`): the X-Forwarded-Proto / X-Forwarded-Protocol / X-Url-Scheme headers were returned verbatim whenever non-empty, so a bogus value (e.g. `X-Forwarded-Proto: invalid`) was returned as the scheme instead of being ignored, and no fallback to `http` happened. There was no helper function at all; the header values were used raw.

**Fix (only file changed by me: `/echo/context.go`)** — added a small `schemeFromHeader` helper that only accepts `http`/`https` (case-insensitive) and returns `""` otherwise, and used it for the three scheme headers. Precedence (TLS → X-Forwarded-Proto → X-Forwarded-Protocol → X-Forwarded-Ssl: on → X-Url-Scheme → "http") is unchanged.

```diff
@@ -255,21 +255,31 @@ func (c *context) Scheme() string {
 	if c.IsTLS() {
 		return "https"
 	}
-	if scheme := c.request.Header.Get(HeaderXForwardedProto); scheme != "" {
+	if scheme := schemeFromHeader(c.request.Header, HeaderXForwardedProto); scheme != "" {
 		return scheme
 	}
-	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); scheme != "" {
+	if scheme := schemeFromHeader(c.request.Header, HeaderXForwardedProtocol); scheme != "" {
 		return scheme
 	}
 	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
 		return "https"
 	}
-	if scheme := c.request.Header.Get(HeaderXUrlScheme); scheme != "" {
+	if scheme := schemeFromHeader(c.request.Header, HeaderXUrlScheme); scheme != "" {
 		return scheme
 	}
 	return "http"
 }

+// schemeFromHeader returns the value of the given header when it holds a valid
+// HTTP scheme (`http` or `https`). Any other value is ignored so that the next
+// header is consulted and the scheme eventually falls back to `http`.
+func schemeFromHeader(header http.Header, name string) string {
+	if scheme := header.Get(name); strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https") {
+		return scheme
+	}
+	return ""
+}
+
 func (c *context) RealIP() string {
