```go
func (b *DefaultBinder) bindData(destination interface{}, data map[string][]string, tag string) error {
	if destination == nil || len(data) == 0 {
		return nil
	}
	typ := reflect.TypeOf(destination).Elem()
	val := reflect.ValueOf(destination).Elem()

	// Support binding to limited Map destinations:
	// - map[string][]string,
	// - map[string]string <-- (binds first value from data slice)
	// - map[string]interface{} <-- (binds first value from data slice)
	// - map[string]interface{} with nested map[string]interface{} (JSON only)
	// - map[string]string with nested map[string]string (JSON only)
	if typ.Kind() == reflect.Map && typ.Key().Kind() == reflect.String {
		// check if we are binding to map[string]interface{} or map[string]string
		switch typ.Elem().Kind() {
		case reflect.Slice:
			if typ.Elem().Elem().Kind() != reflect.String {
				return fmt.Errorf("%w, only map[string][]string, map[string]string and map[string]interface{} type maps are supported", ErrUnsupportedType)
			}
		case reflect.String, reflect.Interface:
		default:
			return fmt.Errorf("%w, only map[string][]string, map[string]string and map[string]interface{} type maps are supported", ErrUnsupportedType)
		}

		if val.IsNil() {
			val.Set(reflect.MakeMap(typ))
		}

		for k, v := range data {
			switch typ.Elem().Kind() {
			case reflect.Slice:
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
			case reflect.String:
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
			case reflect.Interface:
				val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
			}
		}
		return nil
	}
```

