// bindDataToMap binds data to a map destination. Only limited map types are supported:
// - map[string][]string
// - map[string]string <-- (binds first value from data slice)
// - map[string]interface{}
// You are better off binding to struct as Go does not support binding to maps with
// arbitrary types.
// Optional arguments are ignored; they exist so that callers which already resolved the
// destination type and value can pass them along.
func (b *DefaultBinder) bindDataToMap(destination interface{}, data map[string][]string, _ ...interface{}) error {
	val := reflect.ValueOf(destination)
	if val.Kind() == reflect.Ptr {
		val = val.Elem()
	}
	if !val.IsValid() || val.Kind() != reflect.Map {
		return errors.New("binding element must be a map")
	}
	typ := val.Type()
	if typ.Key().Kind() != reflect.String {
		return errors.New("binding element must be a map with string keys")
	}

	k := typ.Elem().Kind()
	isElemInterface := k == reflect.Interface
	isElemString := k == reflect.String
	isElemSliceOfStrings := k == reflect.Slice && typ.Elem().Elem().Kind() == reflect.String

	if !(isElemSliceOfStrings || isElemString || isElemInterface) {
		return nil
	}
	if val.IsNil() {
		if !val.CanSet() {
			return errors.New("binding element must be a pointer to a map")
		}
		val.Set(reflect.MakeMap(typ))
	}
	for k, v := range data {
		if isElemString {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v[0]))
		} else {
			val.SetMapIndex(reflect.ValueOf(k), reflect.ValueOf(v))
		}
	}
	return nil
}
